from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        # dp[alt_sum] = max product achievable with that alternating sum
        # Use -inf for unreachable states
        NEG_INF = float('-inf')

        # Offset for alternating sum: range is roughly [-sum(nums), sum(nums)]
        # Max sum is 150 * 12 = 1800, so offset by 1800
        offset = 1800
        size = 2 * offset + 1

        dp = [NEG_INF] * size
        dp[offset] = 1  # empty subsequence has alt_sum=0, product=1

        for num in nums:
            new_dp = dp[:]  # not taking num
            for s in range(size):
                if dp[s] != NEG_INF:
                    # Take num at even position (add to alt_sum)
                    new_s = s + num
                    if 0 <= new_s < size:
                        new_prod = dp[s] * num
                        if new_prod <= limit:
                            new_dp[new_s] = max(new_dp[new_s], new_prod)

                    # Take num at odd position (subtract from alt_sum)
                    new_s = s - num
                    if 0 <= new_s < size:
                        new_prod = dp[s] * num
                        if new_prod <= limit:
                            new_dp[new_s] = max(new_dp[new_s], new_prod)
            dp = new_dp

        # We need non-empty subsequence with alt_sum == k
        # But we also need to track parity of subsequence length
        # Actually, the alternating sum depends on position in subsequence
        # We need to track whether next element goes to even or odd position

        # Redo with parity tracking
        # dp[parity][alt_sum] = max product
        # parity 0: next element at even position (add)
        # parity 1: next element at odd position (subtract)

        dp = [[NEG_INF] * size for _ in range(2)]
        dp[0][offset] = 1  # empty, next at even position

        for num in nums:
            new_dp = [row[:] for row in dp]  # not taking num
            for parity in range(2):
                for s in range(size):
                    if dp[parity][s] != NEG_INF:
                        new_prod = dp[parity][s] * num
                        if new_prod > limit:
                            continue
                        if parity == 0:
                            # num at even position, add to sum
                            new_s = s + num
                            new_parity = 1
                        else:
                            # num at odd position, subtract from sum
                            new_s = s - num
                            new_parity = 0
                        if 0 <= new_s < size:
                            new_dp[new_parity][new_s] = max(
                                new_dp[new_parity][new_s], new_prod
                            )
            dp = new_dp

        # Find max product with alt_sum == k, non-empty subsequence
        target = k + offset
        if not (0 <= target < size):
            return -1

        result = -1
        for parity in range(2):
            if dp[parity][target] != NEG_INF and dp[parity][target] > 0:
                # Exclude empty subsequence case (product=1, alt_sum=0)
                if not (k == 0 and dp[parity][target] == 1):
                    result = max(result, dp[parity][target])

        # Handle edge case: if k == 0 and only empty subsequence works
        # We need to ensure non-empty
        # Actually, we need to track if subsequence is non-empty separately

        # Redo with empty tracking
        # dp[parity][alt_sum] = (max_product, is_non_empty_possible)
        # Better: track max product for empty and non-empty separately

        dp_empty = [[NEG_INF] * size for _ in range(2)]
        dp_nonempty = [[NEG_INF] * size for _ in range(2)]
        dp_empty[0][offset] = 1

        for num in nums:
            new_empty = [row[:] for row in dp_empty]
            new_nonempty = [row[:] for row in dp_nonempty]

            for parity in range(2):
                for s in range(size):
                    # From empty state
                    if dp_empty[parity][s] != NEG_INF:
                        new_prod = dp_empty[parity][s] * num
                        if new_prod <= limit:
                            if parity == 0:
                                new_s = s + num
                                new_p = 1
                            else:
                                new_s = s - num
                                new_p = 0
                            if 0 <= new_s < size:
                                new_nonempty[new_p][new_s] = max(
                                    new_nonempty[new_p][new_s], new_prod
                                )

                    # From non-empty state
                    if dp_nonempty[parity][s] != NEG_INF:
                        new_prod = dp_nonempty[parity][s] * num
                        if new_prod <= limit:
                            if parity == 0:
                                new_s = s + num
                                new_p = 1
                            else:
                                new_s = s - num
                                new_p = 0
                            if 0 <= new_s < size:
                                new_nonempty[new_p][new_s] = max(
                                    new_nonempty[new_p][new_s], new_prod
                                )

            dp_empty = new_empty
            dp_nonempty = new_nonempty

        result = -1
        for parity in range(2):
            if dp_nonempty[parity][target] != NEG_INF:
                result = max(result, dp_nonempty[parity][target])

        return result

