def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    A = list(map(int, data[1:1+n]))
    B = list(map(int, data[1+n:1+2*n]))

    a_fixed = [x for x in A if x != -1]
    b_fixed = [x for x in B if x != -1]
    cnt_a = n - len(a_fixed)
    cnt_b = n - len(b_fixed)

    sum_a = sum(a_fixed)
    sum_b = sum(b_fixed)

    if cnt_a == 0 and cnt_b == 0:
        print("Yes" if sum_a == sum_b else "No")
        return

    if cnt_a == 0:
        # cnt_b > 0
        if sum_a >= sum_b:
            print("Yes")
        else:
            print("No")
        return

    if cnt_b == 0:
        # cnt_a > 0
        if sum_b >= sum_a:
            print("Yes")
        else:
            print("No")
        return

    # both cnt_a > 0 and cnt_b > 0
    if sum_a == sum_b:
        print("Yes")
        return

    if sum_a < sum_b:
        # need to add to A
        diff = sum_b - sum_a
        if diff >= cnt_a:
            print("Yes")
        else:
            print("No")
    else:
        # sum_a > sum_b, need to add to B
        diff = sum_a - sum_b
        if diff >= cnt_b:
            print("Yes")
        else:
            print("No")

