class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache

        def count_upto(n: int) -> int:
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            length = len(digits)

            @lru_cache(maxsize=None)
            def dfs(pos: int, tight: bool, started: bool, digit_sum: int, digit_prod: int) -> int:
                if pos == length:
                    if not started:
                        return 0
                    if digit_sum == 0:
                        return 0
                    return 1 if digit_prod % digit_sum == 0 else 0

                limit = digits[pos] if tight else 9
                total = 0
                for d in range(limit + 1):
                    new_tight = tight and (d == limit)
                    new_started = started or (d != 0)
                    new_sum = digit_sum + d
                    if not started and d == 0:
                        new_prod = digit_prod
                    else:
                        new_prod = digit_prod * d
                    total += dfs(pos + 1, new_tight, new_started, new_sum, new_prod)
                return total

            return dfs(0, True, False, 0, 1)

        return count_upto(r) - count_upto(l - 1)

