class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = ['a'] * L
        fixed = [False] * L

        # Apply all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if fixed[pos] and word[pos] != str2[j]:
                        return ""
                    word[pos] = str2[j]
                    fixed[pos] = True

        # Check all 'F' constraints
        for i in range(n):
            if str1[i] == 'F':
                # Check if substring word[i:i+m] equals str2
                match = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        match = False
                        break

                if match:
                    # Find the rightmost non-fixed position in this window
                    change_pos = -1
                    for j in range(m - 1, -1, -1):
                        if not fixed[i + j]:
                            change_pos = i + j
                            break

                    if change_pos == -1:
                        return ""

                    # Change this position to 'b' (smallest char != 'a')
                    word[change_pos] = 'b'

        return ''.join(word)

