class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Precompute factorials up to n
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        # dp[o][e][p]: number of alternating permutations using o odd numbers
        # and e even numbers, where the last number has parity p (0=even, 1=odd).
        # Valid states require |o - e| <= 1.
        dp = [[[0, 0] for _ in range(n + 1)] for _ in range(n + 1)]
        dp[0][0][0] = dp[0][0][1] = 1  # empty sequence base

        for o in range(n + 1):
            for e in range(n + 1):
                if o == 0 and e == 0:
                    continue
                if abs(o - e) > 1:
                    continue
                # last is odd: previous state used o-1 odds, e evens, last even
                if o > 0 and abs((o - 1) - e) <= 1:
                    dp[o][e][1] = dp[o - 1][e][0]
                # last is even: previous state used o odds, e-1 evens, last odd
                if e > 0 and abs(o - (e - 1)) <= 1:
                    dp[o][e][0] = dp[o][e - 1][1]

        num_odds = (n + 1) // 2
        num_evens = n // 2

        # Total valid permutations
        if abs(num_odds - num_evens) > 1:
            return []
        if num_odds == num_evens:
            total = dp[num_odds][num_evens][0] + dp[num_odds][num_evens][1]
        elif num_odds > num_evens:
            total = dp[num_odds][num_evens][1]  # must start and end with odd
        else:
            total = dp[num_odds][num_evens][0]  # must start and end with even

        if k > total:
            return []

        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        result = []
        prev_parity = -1  # -1 means no previous element

        for _ in range(n):
            placed = False
            # Determine which candidate list to try first based on lexicographic order.
            # We simply try all remaining numbers in increasing order.
            candidates = []
            if prev_parity != 1:  # can place odd
                candidates.extend((x, 1) for x in odds)
            if prev_parity != 0:  # can place even
                candidates.extend((x, 0) for x in evens)
            candidates.sort()

            for val, parity in candidates:
                o_rem = len(odds) - (1 if parity == 1 else 0)
                e_rem = len(evens) - (1 if parity == 0 else 0)
                if abs(o_rem - e_rem) > 1:
                    continue
                cnt = dp[o_rem][e_rem][parity]
                if k > cnt:
                    k -= cnt
                else:
                    result.append(val)
                    if parity == 1:
                        odds.remove(val)
                    else:
                        evens.remove(val)
                    prev_parity = parity
                    placed = True
                    break
            if not placed:
                return []  # should not happen if k <= total

        return result

