class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Map each boundary point to a 1D coordinate along the perimeter.
        # Start at (0,0), go up the left side, right along the top,
        # down the right side, then left along the bottom.
        def pos(p):
            x, y = p
            if x == 0:
                return y
            if y == side:
                return side + x
            if x == side:
                return 2 * side + (side - y)
            # y == 0
            return 3 * side + (side - x)

        P = 4 * side
        arr = sorted(pos(p) for p in points)
        n = len(arr)

        # Check whether we can pick at least k points with pairwise
        # Manhattan distance >= d.
        def can(d):
            # Try every point as the first selected point.
            for s in range(n):
                start = arr[s]
                cnt = 1
                last = start
                ok = True
                # Greedily take the next point at distance >= d along the circle.
                for _ in range(k - 1):
                    target = last + d
                    # Binary search in arr for the first value >= target.
                    lo, hi = 0, n
                    while lo < hi:
                        mid = (lo + hi) // 2
                        if arr[mid] < target:
                            lo = mid + 1
                        else:
                            hi = mid
                    if lo == n:
                        ok = False
                        break
                    last = arr[lo]
                    cnt += 1
                if not ok:
                    continue
                # Check wrap-around distance from last selected to first selected.
                if P - (last - start) >= d:
                    return True
            return False

        # Binary search the maximum feasible minimum distance.
        lo, hi = 1, 2 * side
        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

