from collections import deque

def main():
    input = sys.stdin.readline
    N = int(input())
    grid = [input().strip() for _ in range(N)]

    # Build adjacency list: edges[u] = list of (v, label)
    edges = [[] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            c = grid[i][j]
            if c != '-':
                edges[i].append((j, c))

    # dist[i][j] = shortest palindrome path length from i to j
    INF = -1
    dist = [[INF] * N for _ in range(N)]
    dq = deque()

    # Base cases:
    # Length 0: empty string is palindrome, path from i to i
    for i in range(N):
        dist[i][i] = 0
        dq.append((i, i))

    # Length 1: single edge i->j with any label is palindrome
    for i in range(N):
        for j, c in edges[i]:
            if dist[i][j] == INF or dist[i][j] > 1:
                dist[i][j] = 1
                dq.append((i, j))

    # BFS: if we know dist[i][j], we can extend by adding same-labeled edges
    # on both ends: x --c--> i ... j --c--> y gives dist[x][y] = dist[i][j] + 2
    while dq:
        i, j = dq.popleft()
        d = dist[i][j]
        # Try all edges x->i and j->y with same label
        for x in range(N):
            for xi, cx in [(v, c) for v, c in edges[x] if v == i]:
                for y, cy in edges[j]:
                    if cx == cy:
                        if dist[x][y] == INF:
                            dist[x][y] = d + 2
                            dq.append((x, y))

    out = []
    for i in range(N):
        out.append(' '.join(str(dist[i][j]) for j in range(N)))
    sys.stdout.write('\n'.join(out) + '\n')

