MOD = 998244353

def main():
    W, H, L, R, D, U = map(int, sys.stdin.readline().split())
    N = W + H + 5
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i-1] * i % MOD
    inv_fact = [1] * (N + 1)
    inv_fact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        inv_fact[i-1] = inv_fact[i] * i % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n-k] % MOD

    def paths(x1, y1, x2, y2):
        if x2 < x1 or y2 < y1:
            return 0
        return comb(x2 - x1 + y2 - y1, x2 - x1)

    # Region A: x in [0, L-1], y in [0, H]
    ans = 0
    if L > 0:
        ans = (ans + comb(L + H + 2, L + 1) - (H + 1)) % MOD
    # Region B: x in [R+1, W], y in [0, H]
    if R < W:
        ans = (ans + comb(W - R + H + 2, W - R + 1) - (H + 1)) % MOD
    # Region C: x in [L, R], y in [0, D-1]
    if D > 0:
        ans = (ans + comb(R - L + D + 2, R - L + 1) - (R - L + 1)) % MOD
    # Region D: x in [L, R], y in [U+1, H]
    if U < H:
        ans = (ans + comb(R - L + H - U + 2, R - L + 1) - (R - L + 1)) % MOD

    # Cross terms
    # A -> C
    if L > 0 and D > 0:
        s = 0
        for y in range(D):
            s = (s + paths(0, 0, L - 1, y) * paths(L, y, R, D - 1)) % MOD
        ans = (ans + s) % MOD
    # A -> D
    if L > 0 and U < H:
        s = 0
        for y in range(U + 1, H + 1):
            s = (s + paths(0, 0, L - 1, y) * paths(L, y, R, H)) % MOD
        ans = (ans + s) % MOD
    # C -> B
    if D > 0 and R < W:
        s = 0
        for x in range(L, R + 1):
            s = (s + paths(0, 0, x, D - 1) * paths(x, D, W, H)) % MOD
        ans = (ans + s) % MOD
    # D -> B
    if U < H and R < W:
        s = 0
        for x in range(L, R + 1):
            s = (s + paths(0, 0, x, H) * paths(x, U + 1, W, H)) % MOD
        ans = (ans + s) % MOD
    # A -> C -> B
    if L > 0 and D > 0 and R < W:
        s = 0
        for y in range(D):
            for x in range(L, R + 1):
                s = (s + paths(0, 0, L - 1, y) * paths(L, y, x, D - 1) * paths(x, D, W, H)) % MOD
        ans = (ans + s) % MOD
    # A -> D -> B
    if L > 0 and U < H and R < W:
        s = 0
        for y in range(U + 1, H + 1):
            for x in range(L, R + 1):
                s = (s + paths(0, 0, L - 1, y) * paths(L, y, x, H) * paths(x, U + 1, W, H)) % MOD
        ans = (ans + s) % MOD

    print(ans % MOD)

