class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0
        for i in range(n):
            d = ord(s[i]) - 48
            if d == 0:
                continue
            ans += 1  # single digit substring
            rem = 0
            # check substrings ending at i with length up to 9
            start = max(0, i - 8)
            for j in range(i, start - 1, -1):
                digit = ord(s[j]) - 48
                length = i - j + 1
                rem = (digit * pow(10, length - 1, d) + rem) % d
                if rem == 0:
                    ans += 1
        return ans

