class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        # For every non-empty subset of target, compute the LCM of its elements.
        # A single nums element (after increments) can satisfy exactly the targets
        # whose values divide it, i.e. it must become a multiple of the subset's LCM.
        lcms = []
        for mask in range(1, 1 << m):
            l = 1
            for i in range(m):
                if mask >> i & 1:
                    l = lcm(l, target[i])
            lcms.append((mask, l))

        # dp[mask] = min operations to satisfy the set of targets represented by mask
        INF = float('inf')
        dp = [INF] * (1 << m)
        dp[0] = 0

        for x in nums:
            # Cost for this element to cover each subset (become a multiple of its LCM)
            costs = []
            for mask, l in lcms:
                r = x % l
                costs.append(0 if r == 0 else l - r)
            # Update dp in reverse so each nums element is used at most once
            for mask in range((1 << m) - 1, -1, -1):
                if dp[mask] == INF:
                    continue
                for i, (sub, _) in enumerate(lcms):
                    new_mask = mask | sub
                    c = dp[mask] + costs[i]
                    if c < dp[new_mask]:
                        dp[new_mask] = c

        return dp[(1 << m) - 1]

