                    hi = mid
                else:
                    lo = mid + 1
            if lo > cur:
                cur = lo
        L[i] = cur
        stack.append(i)
    # right boundary: maximal index reachable from i, or n+1 if can absorb all to right
    R = [n+1]*(n+2)
    stack = []
    for i in range(n, 0, -1):
        cur = i
        while stack and A[stack[-1]-1] < A[i-1]:
