from typing import List
from collections import defaultdict
import math

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.count = n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return
        if self.rank[rx] < self.rank[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1
        self.count -= 1

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        dsu = DSU(n)
        val_to_idx = {v: i for i, v in enumerate(nums)}

        # Group numbers by their divisors (only divisors <= threshold matter)
        divisor_to_indices = defaultdict(list)
        for i, v in enumerate(nums):
            if v > threshold:
                continue
            for d in range(1, int(math.isqrt(v)) + 1):
                if v % d == 0:
                    if d <= threshold:
                        divisor_to_indices[d].append(i)
                    other = v // d
                    if other != d and other <= threshold:
                        divisor_to_indices[other].append(i)

        # For each divisor g, connect numbers whose pairwise lcm <= threshold
        for g, indices in divisor_to_indices.items():
            m = len(indices)
            if m < 2:
                continue
            # Sort by value to check consecutive pairs
            vals = sorted((nums[i], i) for i in indices)
            for k in range(m - 1):
                a, ia = vals[k]
                b, ib = vals[k + 1]
                # lcm(a, b) = a * b // gcd(a, b), and g divides both
                if a // g * b <= threshold:  # a*b/g <= threshold, since g | gcd(a,b)
                    dsu.union(ia, ib)

        return dsu.count
